 <section class="reference-section"><h2>Palette de référence</h2><div class="swatch-grid"><article v-for="color in reference.colors" :key="color.role" class="swatch-card"><div class="color-swatch" :style="{backgroundColor:color.value}" aria-hidden="true"></div><div class="swatch-description"><code>{{ color.role }}</code><span>{{ color.value }}</span></div></article></div><a class="reference-source" :href="reference.source+'#couleurs'" target="_blank" rel="noopener noreferrer">Voir la palette d’origine</a></section>
